BEGIN;

CREATE TABLE "currency_code_reference" (
  "id" UUID NOT NULL,
  "alpha_code" CHAR(3) NOT NULL,
  "numeric_code" CHAR(3) NOT NULL,
  "minor_unit" INTEGER,
  "currency_name" TEXT NOT NULL,
  "source_version" TEXT NOT NULL,
  "source_url" TEXT NOT NULL,
  "source_sha256" CHAR(64) NOT NULL,
  "records_sha256" CHAR(64) NOT NULL,
  "source_row_hash" CHAR(64) NOT NULL,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "currency_code_reference_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "currency_code_alpha_key" UNIQUE ("alpha_code"),
  CONSTRAINT "currency_code_numeric_key" UNIQUE ("numeric_code"),
  CONSTRAINT "currency_code_reference_shape_check" CHECK (
    "alpha_code" ~ '^[A-Z]{3}$' AND
    "numeric_code" ~ '^[0-9]{3}$' AND
    ("minor_unit" IS NULL OR "minor_unit" BETWEEN 0 AND 9) AND
    length(btrim("currency_name")) > 0 AND
    "source_version" = '2026-09-17' AND
    "source_url" = 'https://www.six-group.com/dam/download/financial-information/data-center/iso-currrency/lists/list-one.xml' AND
    "source_sha256" = '33139b438657d1cee116ba737807ea71d19d6de4b90f799a09c56f0cc6a1b0ff' AND
    "records_sha256" = '10f3266f8cfefacda248330d0612cf3b61febdcb38875432a20025bab607673d' AND
    "source_row_hash" ~ '^[0-9a-f]{64}$'
  )
);

